import{_ as t,o as p,c as a,ah as o}from"./chunks/framework.BdHuibk5.js";const m=JSON.parse('{"title":"曾经沧海难为水","description":"2012 年 7 月 1 日，想起大学里那些人、那些事，也想起如今支离破碎的心情。曾经的自在与热闹都还记得，只是很多东西，终究已经回不去了。","frontmatter":{"title":"曾经沧海难为水","date":"2012-07-01 21:59","category":"diary","tags":["心情","回忆"],"slug":"once-the-sea","layout":"blog-post","description":"2012 年 7 月 1 日，想起大学里那些人、那些事，也想起如今支离破碎的心情。曾经的自在与热闹都还记得，只是很多东西，终究已经回不去了。"},"headers":[],"relativePath":"blog/once-the-sea.md","filePath":"blog/posts/diary/once-the-sea.md","lastUpdated":1789447662000}'),s={name:"blog/once-the-sea.md"};function r(n,e,_,c,d,l){return p(),a("div",null,[...e[0]||(e[0]=[o("<p>今天是 2012 年 07 月 01 日，该散的都散了！</p><p>还记得那年邱生理的那个爆炸头吧？还记得马屁文那时短发粗眉的样子么？还有鸡巴绵的光头。我还记得很清楚。因为，大学的时光是美好难忘的。还记得家和食堂四楼的那次舞会么？为此竟然还 SB 地去学那交际舞；毕竟，那次也让我捡了个师父和师母回来。</p><p>还有那年三个人打台球打到半夜三更，那台球桌老板就等咱们仨到一两点多么？那个是牛逼的露天台球！要不然，怎么可能赢得了小旋子他们寝室，这个还是能一直津津乐道的事，霸气啊！还有科院附近那家雅兔网吧，我把自己的第一次通宵就献给了这狗日的破网吧，整整一个晚上啊，大冬天的被冻了一晚上！还有咱们一起打球的日子，大一那一年，过得真的很开心，很自在，虽然也很二。听小开讲那些在高中时都未曾做过的事，也是晚上的一项活动。</p><p>在 KFC 时的那些事，认识的那些人，我也都不曾遗忘你们中的任何一个，真的！</p><p>还有很多很多，但毕竟已经过去……世上没有什么过不去，只有再也回不去……</p><p>现在的心情，是支离破碎的。也许，一直以来都是这样子的吧。心思始终随风飘荡。曾经的我，调节情绪办法很多，会让自己变得忙碌，到操场上去跑几圈，要么就是打扫寝室弄个干净，可现在，我也不知道该怎么去处理，任其如此，因为自己一直处在消极中，解决了这个，还会有下一个烦恼，那又何必去解决它。也许是因为自己已经压抑得太久太久，也未曾释放发泄。以至于整个人很闷，无法形容的闷。</p><p>身体素质也每况愈下，通宵那就更别说了，能支持到三点，已经不错，可竟有了后遗症，头晕，天旋地转，真的吃不消，美尼尔氏综全症，有点吓人。前段时间不小心食物中毒，半夜三更地吐得不行，人一躺下头就晕，整个人变得很脆弱，不知道该怎么办，我也不知道该对谁说，还想到大学室友们开玩笑说的那些话，我竟然也害怕得不敢躺床上睡觉。</p><p>不知为何，却有了想回家的念头，想跟父母离得近些，这样就能常常吃到妈妈烧的菜，跟他们也可以有更好的沟通和相互照顾。</p><p>性格真的也是会改变的，随着年龄的增长和更多的阅历。我也希望我能回到当初的自己，那个时候的我真的很好。</p><p>有些事也不是我说了就能明白理解的，唯有待时间去证明之。</p><p>曾经沧海难为水……你若安好，便是晴天。</p>",11)])])}const f=t(s,[["render",r]]);export{m as __pageData,f as default};
